/* eslint-disable */
import React from "react";
import { Link } from "react-router-dom";

import IndexNavbar from "components/Navbars/IndexNavbar.js";
import Footer from "components/Footers/Footer.js";
import HeroImage from "assets/img/bg1.png";

// images locales pour remplacer les icônes
import Icon1 from "assets/img/menu.png";
import Icon2 from "assets/img/ressources.png";
import Icon3 from "assets/img/rh.png";
import Icon4 from "assets/img/commercial.png";

export default function Index() {
  // Styles de couleur basés sur l'image
  const BLUE_BG = '#1A202C'; // Le fond principal (très foncé)
  const ACCENT_BLUE = '#2E3A59'; // Une nuance plus claire utilisée pour des blocs
  const WHITE_CARD_BG = 'white'; // Fond des cartes

  // Composant Rendu pour une carte simple
  const Card = ({ title, children, className = '' }) => (
    <div className={`bg-white rounded-xl shadow-lg p-6 ${className}`}>
      <h3 className="text-xl font-semibold mb-4 border-b pb-2 text-gray-800">
        {title}
      </h3>
      {children}
    </div>
  );
  return (
    <>
      <IndexNavbar fixed />

      {/* HERO */}
      <section
        className="relative mt-16 md:mt-20 h-screen max-h-860-px flex items-center"
        style={{
          backgroundImage: `linear-gradient(rgba(107, 20, 15, 0.65), rgba(107, 20, 15, 0.25)), url(${HeroImage})`,
          backgroundSize: "cover",
          backgroundPosition: "center 30%",
          backgroundRepeat: "no-repeat",
        }}
      >
        <div className="container mx-auto relative z-10 flex flex-wrap items-center">
          <div className="w-full lg:w-6/12 px-4">
            <h1 className="font-bold text-5xl md:text-7xl text-white leading-tight">
              Dalal ak jàamm,
            </h1>
            <p className="mt-6 text-2xl md:text-3xl font-light text-white max-w-xl">
              Nassour Abdel-Mahamoud !
            </p>
          </div>
        </div>
      </section>


      {/* BLOCS D’ICÔNES SUPERPOSÉS */}
      <section className="relative z-20 -mt-16">
        <div className="container mx-auto px-4">
          <div className="flex flex-wrap justify-center gap-[6rem]">
            {[
              { img: Icon1, title: "Menu" },
              { img: Icon2, title: "Ressources" },
              { img: Icon3, title: "RH" },
              { img: Icon4, title: "Commercial" },
            ].map((item, idx) => (
              <div
                key={idx}
                // MODIFICATION DE TAILLE ICI : de p-6 w-56 à p-10 w-64
                className="bg-white rounded-2xl shadow-xl p-10 w-64 flex flex-col items-center hover:shadow-2xl transition"
              >
                <img
                  src={item.img}
                  alt={item.title}
                  // Augmente légèrement la taille de l'icône si vous le souhaitez
                  className="w-16 h-26 object-contain mb-6"
                />
                <h6 className="text-xl font-semibold text-blueGray-700 mt-2">
                  {item.title}
                </h6>
              </div>
            ))}
          </div>
        </div>
      </section>

      <div className="min-h-screen bg-gray-100 font-sans">

        {/* Section Supérieure avec le Fond Bleu Foncé et le Contenu en Surimpression */}
        {/* Note : L'image de fond complexe sera un placeholder, le style est le plus important */}
        <div className={`bg-[${BLUE_BG}] relative pb-40`}>

          {/* Navigation/Header (Basé sur l'image fournie) */}
          <header className="flex justify-between items-center p-4 text-white">
            <h1 className="text-2xl font-bold">AccelConnect</h1>
            {/* Espace pour l'avatar ou les icônes de navigation */}
            <div className="flex items-center space-x-4">
              <input
                type="text"
                placeholder="Recherche..."
